+int sw_nb_register(struct net_device *netdev)
+{
+	int err;
+
+	sw_nb_pf_netdev = netdev;
+
+	sw_fdb_init();
+	sw_fib_init();
+	sw_fl_init();
+
+	err = register_switchdev_notifier(&sw_nb_fdb);
+	if (err) {
